import React from 'react';
import { useParams } from 'react-router-dom';
import './ForumDetail.css';

const ForumDetail = ({ forums }) => {
    const { id } = useParams();
    const forum = forums.find(forum => forum.id === parseInt(id));

    if (!forum) {
        return <p>Forum not found</p>;
    }

    const threads = [
        { id: 1, title: "Welcome to Introductions", author: "Admin", date: "2024-08-29" },
        // Autres threads...
    ];

    return (
        <div className="forum-detail">
            <h2>{forum.name}</h2>
            <p>{forum.description}</p>
            <div className="subforums">
                <h3>Subforums</h3>
                <ul>
                    {forum.subForums.map((subForum) => (
                        <li key={subForum.id}>
                            <h4>{subForum.name}</h4>
                            <p>{subForum.description}</p>
                            <div className="last-thread">
                                <p><strong>Last thread:</strong> {subForum.lastThread?.title}</p>
                                <p><em>by {subForum.lastThread?.author} on {subForum.lastThread?.date}</em></p>
                            </div>
                        </li>
                    ))}
                </ul>
            </div>
            <div className="threads">
                <h3>Threads</h3>
                <ul>
                    {threads.map((thread) => (
                        <li key={thread.id}>
                            <h4>{thread.title}</h4>
                            <p><em>by {thread.author} on {thread.date}</em></p>
                        </li>
                    ))}
                </ul>
            </div>
        </div>
    );
};

export default ForumDetail;
